INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "39 + 673 = ___", "hint": "Add the two numbers together.", "explanation": "When you add 39 and 673, you get 712.", "correctAnswer": "712"}, {"id": "q2", "type": "fillInBlank", "question": "9/11 - 4/11 = ___", "hint": "Subtract the numerators while keeping the denominator the same.", "explanation": "Subtracting 4 from 9 gives you 5, so the answer is 5/11.", "correctAnswer": "5/11"}, {"id": "q3", "type": "fillInBlank", "question": "2 \u00d7 45 = ___", "hint": "Multiply the two numbers.", "explanation": "2 times 45 equals 90.", "correctAnswer": "90"}, {"id": "q4", "type": "fillInBlank", "question": "838 \u00f7 1 = ___", "hint": "Dividing any number by 1 gives you the same number.", "explanation": "Any number divided by 1 remains unchanged.", "correctAnswer": "838"}, {"id": "q5", "type": "fillInBlank", "question": "99 \u00f7 11 = ___", "hint": "Think about how many times 11 fits into 99.", "explanation": "11 fits into 99 exactly 9 times.", "correctAnswer": "9"}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as fractions, sequences, and basic arithmetic.', '[{"id": "q1", "type": "fillInBlank", "question": "The next number in the sequence 303,604; 302,604; 301,604; 300,604 is ___", "hint": "Look for the pattern in the sequence.", "explanation": "The sequence decreases by 1,000 each time.", "correctAnswer": "299,604"}, {"id": "q2", "type": "mcq", "question": "How many chocolates did Ken buy if he buys 3 large boxes and 2 small boxes, with each large box containing 48 chocolates and each small box containing 24 chocolates?", "hint": "Calculate the total chocolates from both large and small boxes.", "explanation": "3 large boxes have 144 chocolates and 2 small boxes have 48 chocolates, totaling 192 chocolates.", "correctAnswer": "c", "options": [{"id": "a", "text": "144"}, {"id": "b", "text": "192"}, {"id": "c", "text": "168"}, {"id": "d", "text": "216"}]}, {"id": "q3", "type": "multiSelect", "question": "Tick the two numbers that are equivalent to 1.", "hint": "Think about fractions and their decimal equivalents.", "explanation": "The numbers 1 and 2 are equivalent to 1 when considering whole numbers.", "correctAnswer": ["c", "f"], "options": [{"id": "a", "text": "0.25"}, {"id": "b", "text": "0.5"}, {"id": "c", "text": "2"}, {"id": "d", "text": "100"}, {"id": "e", "text": "25"}, {"id": "f", "text": "1"}]}, {"id": "q4", "type": "fillInBlank", "question": "The volume of a cube with a side length of 20 cm is ___ cm\u00b3.", "hint": "Use the formula for the volume of a cube.", "explanation": "The volume of a cube is calculated as side length cubed: 20 cm \u00d7 20 cm \u00d7 20 cm = 8000 cm\u00b3.", "correctAnswer": "8000"}, {"id": "q5", "type": "mcq", "question": "What is the length of a day on Mercury if it is 58 2/3 times the length of a day on Earth?", "hint": "Multiply the length of a day on Earth by the given factor.", "explanation": "A day on Earth is 24 hours, so 24 hours \u00d7 58 2/3 = 58.67 hours.", "correctAnswer": "a", "options": [{"id": "a", "text": "58.67 hours"}, {"id": "b", "text": "24 hours"}, {"id": "c", "text": "40 hours"}, {"id": "d", "text": "58 hours"}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as sequences, combinations, basic arithmetic, and problem-solving.', '[{"id": "q1", "type": "fillInBlank", "question": "The numbers in this sequence increase by the same amount each time. Write the missing numbers: 42, 49, 63, ___.", "hint": "Look for the common difference between the numbers.", "explanation": "The common difference is 7, so 49 + 7 = 56.", "correctAnswer": "56"}, {"id": "q2", "type": "multiSelect", "question": "Tick the numbers that are common factors of both 12 and 18.", "hint": "Consider the factors of each number.", "explanation": "The common factors of 12 and 18 are 2, 3, and 6.", "correctAnswer": ["a", "b", "c"], "options": [{"id": "a", "text": "2"}, {"id": "b", "text": "3"}, {"id": "c", "text": "6"}, {"id": "d", "text": "9"}, {"id": "e", "text": "12"}]}, {"id": "q3", "type": "mcq", "question": "Jack has \u00a3400 and spends 35% of his money on a new bike. How much does Jack spend on his new bike?", "hint": "Calculate 35% of \u00a3400.", "explanation": "35% of \u00a3400 is \u00a3140 (0.35 * 400 = 140).", "correctAnswer": "a", "options": [{"id": "a", "text": "\u00a3140"}, {"id": "b", "text": "\u00a3120"}, {"id": "c", "text": "\u00a3100"}, {"id": "d", "text": "\u00a3160"}]}, {"id": "q4", "type": "fillInBlank", "question": "A farmer has 980 eggs to pack into boxes that hold six eggs each. How many boxes can the farmer fill? How many eggs will be left over? Full boxes: ___, Left over: ___.", "hint": "Use division to find the number of full boxes and the remainder.", "explanation": "980 divided by 6 gives 163 full boxes with a remainder of 2 eggs.", "correctAnswer": "163, 2"}, {"id": "q5", "type": "fillInBlank", "question": "Amina has read 1/3 of a book with 276 pages. How many pages are left for Amina to read? ___ pages.", "hint": "Calculate 1/3 of 276 and subtract from the total.", "explanation": "1/3 of 276 is 92, so 276 - 92 = 184 pages left.", "correctAnswer": "184"}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Arithmetic Quiz', 'A quiz designed to test basic arithmetic skills including addition, subtraction, multiplication, and division.', '[{"id": "q1", "type": "fillInBlank", "question": "What is 6000 + 90?", "hint": "Think about adding the numbers directly.", "explanation": "When you add 6000 and 90, you simply combine the two values to get 6090.", "correctAnswer": "6090"}, {"id": "q2", "type": "fillInBlank", "question": "What is 8275 + 82?", "hint": "Add the two numbers together.", "explanation": "Adding 8275 and 82 gives you 8357.", "correctAnswer": "8357"}, {"id": "q3", "type": "fillInBlank", "question": "What is 180 \u00f7 3?", "hint": "How many times does 3 go into 180?", "explanation": "Dividing 180 by 3 results in 60.", "correctAnswer": "60"}, {"id": "q4", "type": "mcq", "question": "What is 9 \u00d7 41?", "hint": "Multiply 9 by 40 and then add 9.", "explanation": "9 times 41 equals 369.", "correctAnswer": "a", "options": [{"id": "a", "text": "369"}, {"id": "b", "text": "351"}, {"id": "c", "text": "371"}, {"id": "d", "text": "341"}]}, {"id": "q5", "type": "fillInBlank", "question": "What is 5.87 + 3.123?", "hint": "Align the decimal points before adding.", "explanation": "Adding 5.87 and 3.123 gives you 9.993.", "correctAnswer": "9.993"}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as multiplication, division, sequences, and basic arithmetic.', '[{"id": "q1", "type": "fillInBlank", "question": "What number is 1,000 less than 9,072?", "hint": "Think about subtracting 1,000 from the given number.", "explanation": "To find a number that is 1,000 less than 9,072, you subtract 1,000, resulting in 8,072.", "correctAnswer": "8072"}, {"id": "q2", "type": "mcq", "question": "Which of these shows how to calculate the total cost of tickets if each ticket costs \u00a324 and there is a \u00a33 charge for buying tickets?", "hint": "Consider how to combine the cost of tickets and the additional charge.", "explanation": "The correct calculation is to multiply the number of tickets by the ticket price (\u00a324) and then add the \u00a33 charge, which is represented by option b.", "correctAnswer": "b", "options": [{"id": "a", "text": "number of tickets \u00d7 3 + 24"}, {"id": "b", "text": "number of tickets \u00d7 24 + 3"}, {"id": "c", "text": "number of tickets + 3 \u00d7 24"}, {"id": "d", "text": "number of tickets + 24 \u00d7 3"}]}, {"id": "q3", "type": "multiSelect", "question": "Tick the fractions that are equal to 20%.", "hint": "Convert 20% to a fraction and check which options match.", "explanation": "20% is equivalent to 1/5, and the other fractions can be simplified to show they are also equal to 20%.", "correctAnswer": ["a", "b", "c", "d"], "options": [{"id": "a", "text": "1/5"}, {"id": "b", "text": "20/40"}, {"id": "c", "text": "3/15"}, {"id": "d", "text": "2/100"}]}, {"id": "q4", "type": "fillInBlank", "question": "Write one-quarter of a kilogram as a decimal.", "hint": "Think about how many quarters fit into one whole.", "explanation": "One-quarter of a kilogram is 0.25 kg, as there are four quarters in one whole.", "correctAnswer": "0.25"}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

INSERT INTO math_practice_quizzes (title, description, questions, class_id, created_at) 
VALUES ( 'Mathematics Reasoning Quiz', 'A quiz designed to test reasoning skills in mathematics, covering various topics such as arithmetic, geometry, and number properties.', '[{"id": "q1", "type": "mcq", "question": "What is the sale price of a car originally priced at \u00a38,999 after a discount of \u00a31,100?", "hint": "Subtract the discount from the original price.", "explanation": "The sale price is calculated by subtracting \u00a31,100 from \u00a38,999, which equals \u00a37,899.", "correctAnswer": "a", "options": [{"id": "a", "text": "\u00a37,899"}, {"id": "b", "text": "\u00a38,000"}, {"id": "c", "text": "\u00a38,499"}, {"id": "d", "text": "\u00a39,000"}]}, {"id": "q2", "type": "fillInBlank", "question": "The digit in the ten thousands place of the number 3,576,219 is ___.", "hint": "Look at the number and identify the fifth digit from the right.", "explanation": "In the number 3,576,219, the digit in the ten thousands place is 5.", "correctAnswer": "5"}, {"id": "q3", "type": "multiSelect", "question": "Which of the following expressions shows how much money Dev has left after giving away ''a'' pounds from \u00a310?", "hint": "Think about what happens to the total when money is given away.", "explanation": "The correct expression is 10 - a, which represents the amount left after giving away ''a'' pounds.", "correctAnswer": ["b"], "options": [{"id": "a", "text": "10 + a"}, {"id": "b", "text": "10 - a"}, {"id": "c", "text": "a - 10"}, {"id": "d", "text": "10 \u00f7 a"}]}, {"id": "q4", "type": "fillInBlank", "question": "If John buys one toy car for \u00a31.49 and one pack of stickers for \u00a31.64, how much change does he get from \u00a310? Show your method: \u00a3___", "hint": "Add the prices together and subtract from \u00a310.", "explanation": "The total cost is \u00a31.49 + \u00a31.64 = \u00a33.13. The change from \u00a310 is \u00a310 - \u00a33.13 = \u00a36.87.", "correctAnswer": "6.87"}, {"id": "q5", "type": "mcq", "question": "How many days are there in September, October, and November altogether?", "hint": "Count the days in each month: September has 30, October has 31, and November has 30.", "explanation": "September (30) + October (31) + November (30) = 91 days.", "correctAnswer": "b", "options": [{"id": "a", "text": "90"}, {"id": "b", "text": "91"}, {"id": "c", "text": "92"}, {"id": "d", "text": "93"}]}]', '6c4db2d7-7ad4-4c87-90f6-b65b28b57a56', NOW());

